package com.manishrawat.realestate.servlet; import com.manishrawat.realestate.model.*; import com.manishrawat.realestate.service.PropertyService; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; import java.math.BigDecimal;
@WebServlet("/property") public class PropertyServlet extends HttpServlet{private final PropertyService ps=new PropertyService(); protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");r.setAttribute("properties",ps.search(r.getParameter("city")==null?"":r.getParameter("city"),r.getParameter("type")==null?"":r.getParameter("type")));if("MANAGER".equals(u.getRole()))r.setAttribute("myProperties",ps.manager(u.getId()));r.getRequestDispatcher("/WEB-INF/views/properties.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{User u=(User)r.getSession().getAttribute("user");Property p=new Property();p.setManagerId(u.getId());p.setTitle(r.getParameter("title"));p.setAddress(r.getParameter("address"));p.setCity(r.getParameter("city"));p.setPrice(new BigDecimal(r.getParameter("price")));p.setPropertyType(r.getParameter("type"));p.setBedrooms(Integer.parseInt(r.getParameter("bedrooms")));p.setDescription(r.getParameter("description"));ps.create(p);s.sendRedirect("property");}catch(Exception e){throw new IOException(e);}}}
